import subprocess
def run(txt, extra):
    res=subprocess.run(["./executable","--print"]+extra, input=(txt+"\n").encode(), stdout=subprocess.PIPE)
    return res.stdout.decode(errors='ignore').replace("\x1b","\\e")
for t in ["key=123", "key=123 hello", "level=info", "count=42", "key=\"value\""]:
    print(t, run(t, []))
    print(" disable kv", run(t, ["--disable","key-value-pairs"]))
    print(" disable numbers", run(t, ["--disable","numbers"]))
    print(" disable kv numbers", run(t, ["--disable","key-value-pairs", "--disable","numbers"]) if t!="key=\"value\"" else "skip")
